<script setup>
const route=useRoute();const router=useRouter();const {data:d}=await useFetch('/api/page',{query:computed(()=>({path:route.path,...route.query}))});
const human=s=>s.split('-').map(x=>x.charAt(0).toUpperCase()+x.slice(1)).join(' ');
useHead({title:()=>d.value?.kind==='home'?'Pokédex':(d.value?.title||'Not found')+' – Pokédex'});
function filter(k,v){const query={...route.query,[k]:v};delete query.page;if(!v)delete query[k];router.replace({query})}
const search=ref(String(route.query.q||''));let timer;function searchInput(){clearTimeout(timer);timer=setTimeout(()=>filter('q',search.value),150)}
const methods=computed(()=>{const groups={};for(const m of (d.value?.kind==='pokemon'?d.value.moves:[]))for(const method of m.methods)(groups[method.name]??=[]).push({...m,level:method.level});const order=['level-up','machine','egg','tutor'];return Object.entries(groups).sort(([a],[b])=>{const ai=order.indexOf(a),bi=order.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b)})});
const stats=['HP','Attack','Defense','Sp. Atk','Sp. Def','Speed'];
const relations=[['Super effective against','double_damage_to'],['Not very effective against','half_damage_to'],['No effect against','no_damage_to'],['Weak to','double_damage_from'],['Resists','half_damage_from'],['Immune to','no_damage_from']];
</script>
<template><main v-if="d">
<template v-if="d.kind==='home'"><h1>Pokémon</h1><div class="filters"><label>Search<input v-model="search" type="search" @input="searchInput"></label><div><label for="type-filter">Type</label><select id="type-filter" :value="route.query.type||''" @change="filter('type',$event.target.value)"><option value="">All types</option><option v-for="t in d.types" :key="t.name" :value="t.name">{{human(t.name)}}</option></select></div><div><label for="generation-filter">Generation</label><select id="generation-filter" :value="route.query.generation||''" @change="filter('generation',$event.target.value)"><option value="">All generations</option><option v-for="g in d.generations" :key="g.name" :value="g.name">{{g.label}}</option></select></div></div><p class="muted">{{d.total}} Pokémon</p><PokemonCards v-if="d.total" :items="d.cards"/><p v-else>No Pokémon found</p><div class="pagination"><NuxtLink v-if="d.page>1" :to="{query:{...route.query,page:d.page===2?undefined:d.page-1}}">Previous page</NuxtLink><span>Page {{d.page}} of {{d.pages}}</span><NuxtLink v-if="d.page<d.pages" :to="{query:{...route.query,page:d.page+1}}">Next page</NuxtLink></div></template>
<template v-else-if="d.kind==='pokemon'"><div class="summary"><img class="artwork" :src="d.p.sprites.other['official-artwork'].front_default" :alt="d.title"><div><span class="dex">#{{String(d.s.id).padStart(4,'0')}}</span><h1>{{d.title}}</h1><p class="muted genus">{{d.s.genera.find(g=>g.language.name==='en')?.genus}}</p><div class="badges"><TypeBadge v-for="t in d.p.types" :key="t.slot" :name="t.type.name" linked/></div><dl class="measurements"><div><dt>Height</dt><dd>{{(d.p.height/10).toFixed(1)}} m</dd></div><div><dt>Weight</dt><dd>{{(d.p.weight/10).toFixed(1)}} kg</dd></div></dl><p>{{d.flavor}}</p></div></div>
<section aria-labelledby="stats"><h2 id="stats">Base stats</h2><table class="stats"><tbody><tr v-for="(s,i) in d.p.stats" :key="s.stat.name"><th scope="row">{{stats[i]}}</th><td>{{s.base_stat}}</td><td><div class="track"><div :style="{width:s.base_stat/255*100+'%'}"></div></div></td></tr><tr><th scope="row">Total</th><td>{{d.p.stats.reduce((n,s)=>n+s.base_stat,0)}}</td><td><div class="track"><div :style="{width:d.p.stats.reduce((n,s)=>n+s.base_stat,0)/1530*100+'%'}"></div></div></td></tr></tbody></table></section>
<section aria-labelledby="abilities"><h2 id="abilities">Abilities</h2><ul><li v-for="a in d.p.abilities" :key="a.slot"><NuxtLink :to="'/abilities/'+a.ability.name">{{human(a.ability.name)}}</NuxtLink><span v-if="a.is_hidden"> (hidden)</span></li></ul></section>
<section aria-labelledby="evolution"><h2 id="evolution">Evolution</h2><EvolutionTree :nodes="[d.chain]"/></section>
<section id="moves" aria-labelledby="moves-title"><h2 id="moves-title">Moves</h2><div class="game"><label for="game-filter">Game</label><select id="game-filter" :value="d.game" @change="router.replace({query:{...route.query,game:$event.target.value},hash:route.hash})"><option v-for="g in d.games" :key="g" :value="g">{{human(g)}}</option></select></div><MoveTable v-for="[method,moves] in methods" :key="d.game+method" :method="method" :moves="moves"/></section></template>
<template v-else><h1>{{d.title}}</h1>
<template v-if="d.kind==='types-list'"><ul class="type-list"><li v-for="t in d.types" :key="t.name"><TypeBadge :name="t.name" linked/></li></ul></template>
<template v-if="d.kind==='moves'"><dl class="details"><dt>Type</dt><dd><TypeBadge :name="d.r.type.name" linked/></dd><dt>Category</dt><dd>{{human(d.r.damage_class.name)}}</dd><dt>Power</dt><dd>{{d.r.power??'—'}}</dd><dt>Accuracy</dt><dd>{{d.r.accuracy??'—'}}</dd><dt>PP</dt><dd>{{d.r.pp??'—'}}</dd></dl></template>
<template v-if="['moves','abilities'].includes(d.kind)"><section aria-labelledby="effect"><h2 id="effect">Effect</h2><p>{{d.effect}}</p></section></template>
<template v-if="d.kind==='types'"><section aria-labelledby="relations"><h2 id="relations">Damage relations</h2><dl class="details relations"><template v-for="[label,key] in relations" :key="key"><dt>{{label}}</dt><dd><template v-if="d.r.damage_relations[key].length"><TypeBadge v-for="t in d.r.damage_relations[key]" :key="t.name" :name="t.name" linked/></template><template v-else>None</template></dd></template></dl></section></template>
<section v-if="d.cards" aria-labelledby="cards-heading"><h2 id="cards-heading">{{d.kind==='moves'?'Learned by':'Pokémon'}}</h2><p class="muted">{{d.cards.length}} Pokémon</p><PokemonCards :items="d.cards"/></section>
<section v-if="d.kind==='types'" aria-labelledby="type-moves"><h2 id="type-moves">Moves</h2><p class="muted">{{d.r.moves.length}} moves</p><ul class="move-list"><li v-for="m in [...d.r.moves].sort((a,b)=>a.name.localeCompare(b.name))" :key="m.name"><NuxtLink :to="'/moves/'+m.name">{{human(m.name)}}</NuxtLink></li></ul></section>
<p v-if="d.kind==='missing'"><NuxtLink to="/">Back to Pokémon</NuxtLink></p></template>
</main></template>
